//! Dataset own-key snapshots retain exact native code units and actual attribute order.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_integrity_queries_reflect_actual_native_extensibility_without_mutation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;d.first='one';d['x\ud800']='raw\udfff';var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});if(Object.isExtensible(d)!==true||Object.isSealed(d)!==false||Object.isFrozen(d)!==false||d!==n.dataset||Object.keys(d).length!==2||watch.takeRecords().length)throw 'actual native integrity queries';var desc=Object.getOwnPropertyDescriptor(d,'x\ud800');if(!desc.writable||!desc.enumerable||!desc.configurable||desc.value!=='raw\udfff')throw 'query preserved native descriptors';"#);}

#[test]
fn dataset_integrity_prevention_seal_and_freeze_throw_typeerror_even_when_empty_and_recover(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var populated of [false,true]){var n=document.createElement('p'),d=n.dataset;if(populated)d['x\ud800']='before';var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});for(var method of ['preventExtensions','seal','freeze']){var caught;try{Object[method](d);}catch(e){caught=e;}if(!(caught instanceof TypeError)||caught instanceof DOMException||Object.isExtensible(d)!==true||Object.isSealed(d)!==false||Object.isFrozen(d)!==false||watch.takeRecords().length||Object.keys(d).length!==(populated?1:0))throw 'native failure leaves extensible attribute backing';if(!Reflect.set(d,'recovery','yes')||d.recovery!=='yes'||watch.takeRecords().length!==1)throw 'write after failed integrity';delete d.recovery;watch.takeRecords();}}"#);}

#[test]
fn dataset_integrity_ordinary_prototype_lookalikes_retain_ordinary_integrity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,fake=Object.create(DOMStringMap.prototype);fake['x\ud800']='ordinary';if(Object.freeze(fake)!==fake||Object.isExtensible(fake)!==false||Object.isFrozen(fake)!==true||Object.isSealed(fake)!==true)throw 'ordinary lookalike freezes';if(Reflect.set(fake,'x\ud800','denied')!==false||n.hasAttribute('data-x\ufffd'))throw 'ordinary store remains separate';if(Object.freeze(DOMStringMap.prototype)!==DOMStringMap.prototype||!Object.isFrozen(DOMStringMap.prototype))throw 'interface prototype ordinary';if(Object.isExtensible(d)!==true||!Reflect.set(d,'x\ud800','native')||d['x\ud800']!=='native')throw 'prototype integrity cannot freeze native backing';"#);}

#[test]
fn dataset_integrity_no_author_coercion_or_prototype_getters(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,hits=0;for(var key of ['valueOf','toString','isExtensible','freeze'])Object.defineProperty(DOMStringMap.prototype,key,{get:function(){hits++;throw 'author getter';},configurable:true});Object.defineProperty(DOMStringMap.prototype,Symbol.toPrimitive,{get:function(){hits++;throw 'coercion getter';},configurable:true});if(!Object.isExtensible(d)||Object.isSealed(d)||Object.isFrozen(d))throw 'native query';for(var method of ['preventExtensions','seal','freeze']){var caught;try{Object[method](d);}catch(e){caught=e;}if(!(caught instanceof TypeError))throw 'real native TypeError';}if(hits)throw 'integrity invoked author property';"#);}

#[test]
fn dataset_integrity_borrowed_methods_return_booleans_and_native_typeerror(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var d=document.getElementById('target').dataset,extensible=Object.isExtensible,sealed=Object.isSealed,frozen=Object.isFrozen,prevent=Object.preventExtensions;if(extensible.call({},d)!==true||sealed.apply(null,[d])!==false||frozen.call(undefined,d)!==false)throw 'borrowed query receiver is argument';var caught;try{prevent.call({toString:function(){throw 'unused this';}},d);}catch(e){caught=e;}if(!(caught instanceof TypeError)||caught.constructor!==TypeError||typeof caught.message!=='string')throw 'canonical TypeError';"#);}

#[test]
fn dataset_integrity_html_svg_failed_integrity_keeps_raw_native_attributes_live(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset;d['x\ud800Name']='native';for(var method of ['preventExtensions','seal','freeze']){var caught;try{Object[method](d);}catch(e){caught=e;}if(!(caught instanceof TypeError)||!Object.isExtensible(d)||Object.isFrozen(d)||Object.isSealed(d)||n.getAttributeNS(null,'data-x\ud800-name')!=='native')throw 'HTML SVG native policy';}d.next='next';delete d['x\ud800Name'];if(Object.keys(d).length!==1||d.next!=='next')throw 'native mutation after all failures';}"#);}

#[test]
fn dataset_integrity_does_not_copy_attribute_names_or_values_or_reserve_retained_storage(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!(r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','{}');"#,"x".repeat(16000)));let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;p.begin_job();p.state.copy_work=0;p.state.retained_limit=p.state.retained;p.runtime.execute(r#"if(Object.isExtensible(data)!==true||Object.isSealed(data)!==false||Object.isFrozen(data)!==false)throw 'constant native integrity';for(var method of ['preventExtensions','seal','freeze']){var caught;try{Object[method](data);}catch(e){caught=e;}if(!(caught instanceof TypeError))throw 'native integrity requires no DOM copies';}"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap();assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,r#"data.recovered='yes';if(data.recovered!=='yes')throw 'recovery';"#);}
#[test]
fn dataset_integrity_work_deadline_refusal_is_atomic_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;data['x\ud800']='old';var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for expired in [false,true]{p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let error=p.runtime.execute("Object.isExtensible(data);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(if expired{"computation time"}else{"DOM work"}),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.execution_deadline=None;run(&mut d,&mut f,&mut p,r#"if(!Object.isExtensible(data)||Object.isFrozen(data)||Object.isSealed(data)||watch.takeRecords().length||data['x\ud800']!=='old')throw 'native integrity refusal recovery';"#);}}
